"""Approved five-group G-Map review, using the established GOSO canvas."""
from pathlib import Path
import shutil
ROOT=Path(__file__).resolve().parents[1]
FIGURES=[
 ('world','GOVERNANCE & PUBLIC GOODS','全球治理与公共品全景',[('supply','治理组织'),('maintenance','共同维护'),('application','公共应用')],'同一地图 · 三类地理关系','组织登记地、维护者所在地与应用所在地分开观察。地图点位和数量均为模拟，各层不能相加；无数据地区不表示没有活动。'),
 ('governance','RULES & PARTICIPATION','治理结构与制度演进',[('practices','治理实践'),('roles','治理角色'),('foundation','五年演进'),('licenses','许可选择')],'制度记录 · 角色分工 · 五年序列','实践与角色使用虚构项目；基金会、许可证、木兰序列保留仓库原值，待核验。贡献份额不代表治理权，组织形式不代表治理质量。'),
 ('support','MAINTENANCE & SUSTAINABILITY','维护与可持续支持',[('scatter','依赖与支持'),('workload','维护负担'),('funding','支持结构'),('succession','人员接续')],'谁在使用 · 谁在维护 · 谁在支持','全部为虚构项目与模拟序列。资金月数为已确认可用资金 / 月维护预算的情景值；参考线可调整，不构成安全或资助判定。'),
 ('public','PUBLIC USE & EVIDENCE','公共服务与受益证据',[('evidence','场景与证据'),('partnership','本地共建'),('outcomes','效果观察')],'从公共目标到部署，再到结果证据','各证据层级为嵌套集合，不能相加。案例、数量和效果均为模拟；DPG 名录认可、具体部署与结果评价分别查证。'),
 ('ai','RESPONSIBILITY IN THE AI ERA','AI 时代的开源责任',[('matrix','跨资产责任'),('review','贡献与评审'),('permissions','Agent 权限')],'来源可追溯 · 责任可识别 · 权限可撤回','全部为模拟演示。检查项逐项显示，不合成任意总分；AI 辅助标记需来自披露或账户记录，不依据文本风格猜测。')
]
INTRO=[
 ('治理、维护和应用，分别发生在哪里？','沿用前几节的全球地图入口，切换三个空间层次：提供治理支持的组织、持续参与维护的人，以及技术进入公共服务的地点。点选地区查看模拟结构，也可隐藏模拟数据，查看正式接数后的空缺状态。','空间差异是合作问题的入口。','全球组织的总部所在地不能代表其全部服务范围。正式研究应连接项目、组织与本地实施伙伴，追问应用地区是否也能参与维护和决策，而不是按点位数量给国家治理能力排名。'),
 ('组织形式之外，看规则是否可查、角色是否可进入。','把决策记录、维护者晋升、利益冲突披露、申诉、安全响应和退出交接放在同一张实践矩阵中。再分别观察贡献、评审、合并、发布和委员会角色，最后回到已有五年序列。','数量与影响份额已有变化，治理成效仍需更多证据。','仓库原表中，基金会活跃仓库由 2022 年的 3,163 个增至 2026 年的 3,350 个，约增长 5.9%；基金会项目 OpenRank 份额由 2.63% 升至 2.93%，增加 0.30 个百分点。这两条序列各自描述规模与影响份额，不能替代基金会托管比例或治理质量。'),
 ('被广泛依赖的项目，能否获得持续维护？','以依赖规模、资金可支持月数和维护者数量建立第一层观察，进一步查看评审积压、支持来源和关键角色接续。重点是识别值得访谈与支持的项目处境，而不是用单一活跃指标判断项目健康。','支持应覆盖日常维护，也应覆盖平稳交接。','模拟散点帮助讨论“高依赖、低支持”的交集；正式结论还需要核对项目预算、志愿投入和变更需求。文档、翻译、安全修复、发布管理和合理归档，都应进入持续支持的范围。'),
 ('公共价值，需要从目标走到可查证的使用与结果。','覆盖健康、教育、农业、气候、灾害、无障碍、公共管理和普惠金融。逐层区分项目声称服务什么目标、是否有具体部署，以及是否存在结果评价；继续追问谁提出需求、谁完成适配、谁承担长期运维。','本地参与和结果证据，让公益叙事更具体。','项目下载、部署地点、注册账户、实际服务人数与社会结果是不同对象。DPG 认可关注核心方案，不能替代每个本地实施的效果证据。正式案例需要保留实施方、时间、来源与评估方法，也要报告没有观察到改善的结果。'),
 ('代码、模型和数据扩张时，责任能力是否同步？','承接 2.5 的资产供给观察，转向责任入口、来源版本、使用条件、本地评测以及变更撤回机制。将 AI 参与协作与人工评审放在一起，并通过权限矩阵讨论 Agent 的授权边界。','自动化能力与责任安排需要共同建设。','发布更多资产并不自动形成可追溯的责任关系。项目应能说明谁接收反馈、谁批准合并与发布，以及问题出现后如何修复、通知和撤回。透明材料、适用性评测和实际治理运行仍需分别验证。')
]
def figure(i):
 key,en,title,tabs,context,caption=FIGURES[i-1]
 return f'''<figure id="fig-2-7-{i}" class="gm-figure"><div class="gm-stage goso-unified-canvas" data-lang="zh" data-slide-key="gmap-{i}" data-slide-height="820" role="group" aria-label="{title}"><div class="gm-board"><header class="gm-board-head"><div><span class="gm-eyebrow">图 2-7-{i} / {en}</span><h4>{title}</h4></div><button data-gm-source="{key}">口径与来源</button></header><div class="gm-toolbar"><div class="gm-tabs" aria-label="{title}视图">{''.join(f'<button data-gm-tab="{key}:{v}" aria-pressed="{str(j==0).lower()}">{label}</button>' for j,(v,label) in enumerate(tabs))}</div><span class="gm-context">{context}</span></div><div id="gm-{key}" class="gm-panel" aria-live="polite"></div><footer class="gm-board-foot"><span id="gm-{key}-foot"></span><a href="/assets/gmap/source-manifest.json" download>来源清单 ↓</a></footer><div class="gm-source-overlay" data-gm-overlay="{key}" role="region" aria-label="口径与来源" hidden></div></div></div><figcaption>{caption}</figcaption></figure>'''
def section(lang='zh'):
 if lang!='zh':return '<section id="ch02-s07"><h2>2.7 Global open-source governance and public benefit map (G-Map)</h2><p>The five-group interactive review is currently available in Chinese.</p><a href="/2026/zh/chapters/02/#ch02-s07">Open G-Map →</a></section>'
 out=['''<section id="ch02-s07" class="chapter-section goso-section gmap-review"><div class="section-topline">2.7 / G-MAP</div><h2>全球开源治理与社会公益地图（G-Map）</h2><p class="goso-question">全球开源由谁共同治理，如何获得持续支持，又怎样形成可验证的公共价值？</p><div class="goso-map-position"><strong>目标与指标定位</strong><p>本节对应 OSDGs 的 X4“开源善治与公共价值”，连接 OSDI 的 4.1“治理成熟度”与 4.2“公共福祉”。以中立托管、治理角色、许可记录、数字公共品共建和 AI 资产透明度建立证据入口。新增图组提供诊断与案例观察，不自动扩充正式指标，也不生成国家治理总分。</p><a href="/2026/zh/data/indicators/">回到第一章的 OSDI 指标词典 →</a></div><h3>核心发现与待检验命题</h3><p><strong>开放协作要成为长期可用的公共技术基础，需要把治理、维护和本地使用联系起来。</strong>前六节呈现参与、贡献、影响、人才、资产与跨地域协作。本节继续追问：谁参与决策，谁承担维护，公共应用又有哪些可查证的结果。</p><div class="gm-findings"><p><b>01 · 已有序列</b>基金会活跃仓库五年约增长 5.9%，影响份额增加 0.30 个百分点；样本与时间口径待核验。</p><p><b>02 · 待检验命题</b>高依赖项目的支持是否充足，贡献地区能否进入维护与决策，需要角色和资源证据。</p><p><b>03 · 待检验命题</b>公共应用和 AI 资产增长，是否伴随本地能力、结果证据与责任机制的积累？</p></div><p class="gm-review-banner"><strong>审阅样稿 · 五组图，充分展开</strong>新增数量、地区分布和案例均使用模拟演示，非实测、非预测。仅图 2-7-2 的基金会、许可证和木兰序列来自仓库已有表，仍待口径与复现核验。</p><nav class="goso-map-route" aria-label="治理公益图组"><a href="#fig-2-7-1">01 全球全景</a><a href="#fig-2-7-2">02 治理规则</a><a href="#fig-2-7-3">03 维护支持</a><a href="#fig-2-7-4">04 公共价值</a><a href="#fig-2-7-5">05 AI 责任</a></nav>''']
 for i,(title,desc,insight,body) in enumerate(INTRO,1):
  out.append(f'<section class="gm-section"><div class="gm-section-head"><span>0{i} / {FIGURES[i-1][2]}</span><div><h3>{title}</h3><p>{desc}</p></div></div>'+figure(i)+f'<div class="gm-insight"><b>洞察 0{i}</b><div><h4>{insight}</h4><p>{body}</p></div></div></section>')
 actions=[('建立可追溯的治理公共底座','由基金会、平台、科研机构和公共部门共同维护项目身份、治理角色、许可、关键决策与版本记录。提供适合项目规模的基础模板，让小社区也能以较低负担说明谁负责、怎样加入、如何反馈。','观察进展：治理记录、有效责任入口、决策与更新记录；同时报告未检查项目。'),('为长期维护配置持续资源','公共资助方、企业使用方与基金会，把关键依赖维护、安全修复、文档、翻译和人员接续纳入支持安排。兼顾成熟基础项目与新生社区，为合理归档、迁移和交接预留资源。','观察进展：维护持续性、角色接续、响应分布与支持来源；保留同类与历史比较。'),('让公共应用成为本地共同创造','围绕明确的公共需求，由当地实施机构与社区参与选择、设计、部署和评价。将本地适配、培训、反馈上游与持续运维作为交付的一部分，并记录公共结果。','观察进展：可验证部署、本地维护参与、公开结果材料与上游回馈。')]
 out.append('<section class="gm-actions"><span class="gm-eyebrow">FROM GOVERNANCE TO PUBLIC VALUE</span><h3>三个行动主张：可追溯、可持续、共同创造。</h3><div>'+''.join(f'<article><b>0{i}</b><h4>{title}</h4><p>{body}</p><small>{note}</small></article>' for i,(title,body,note) in enumerate(actions,1))+'</div></section>')
 out.append('''<details class="gm-methods"><summary>资料、指标边界与后续补数</summary><p>报告年按现行指标词典为上年 7 月 1 日至当年 6 月 30 日；三份已有 CSV 是否按该窗口生成仍待核验。组织与 DPG 名录快照应独立记录核验日期。NeutralityRatio 需要同范围托管与项目分母；GovBalance 需要实际治理角色；ComplianceLicenseCov 需要受检总体与未知许可。现有图不能直接替代这三个指标。</p><p>DPGCoCreation 需要身份核验及共建记录；LicenseOpenness 需要预先定义许可类别；AIAssetTransparency 需要适用检查项、完成检查数和未检查数。透明材料存在不证明内容真实，许可宽松不自动代表更高公共价值。</p><p>优先补充：组织—项目—地区关系、实际治理角色、维护预算与依赖、部署实施方与结果来源、代码—模型—数据责任记录。未知、未发现、未检查、不适用和仅自述待核验分别存储。</p><p><a href="/assets/gmap/simulation.json" download>下载全部模拟底表 ↓</a> · <a href="/assets/gmap/source-manifest.json" download>来源与文件清单 ↓</a></p><p>研究参考：<a href="https://www.digitalpublicgoods.net/standard" target="_blank" rel="noopener">DPG Standard</a> · <a href="https://www.digitalpublicgoods.net/registry" target="_blank" rel="noopener">DPG Registry</a> · <a href="https://www.chaoss.community/practitioner-guide-viability/" target="_blank" rel="noopener">CHAOSS 项目可持续性</a> · <a href="https://openssf.org/projects/scorecard/" target="_blank" rel="noopener">OpenSSF Scorecard</a> · <a href="https://huggingface.co/docs/hub/model-cards" target="_blank" rel="noopener">模型卡</a>。这些参考提供方法入口，不构成本报告模拟对象的外部认可。</p></details><p class="goso-bridge">七个主题从参与走向公共价值：开放生态的长期发展，既需要更多人创造和共享，也需要共同制定规则、持续承担维护，并在具体公共场景中验证价值。</p><div class="gm-end-nav"><a href="#ch02-s06">← 回看跨国协作 D-Map</a><a href="#goso-review">进入本章集中评审 →</a></div><noscript><p>交互图需要启用 JavaScript。模拟底表与来源清单可通过上方链接下载。</p></noscript></section>''')
 return ''.join(out)
def export(out):
 shutil.copytree(ROOT/'content/gmap',out/'assets/gmap',dirs_exist_ok=True)
 for name in ['gmap.js','gmap.css']:shutil.copy2(ROOT/'web'/name,out/name)
